import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"66. Memory Mapping (mmap)","description":"The Little Book of C — 66. Memory Mapping (mmap)","frontmatter":{"title":"66. Memory Mapping (mmap)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 66. Memory Mapping (mmap)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":66,"sidebarWeight":66,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/066-Memory Mapping (mmap)","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/066-Memory Mapping (mmap)"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/066-Memory Mapping (mmap).md","filePath":"posts/c教程/en-US/07-Working Close to the System/066-Memory Mapping (mmap).md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/07-Working Close to the System/066-Memory Mapping (mmap).md"};function i(l,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/066-Memory Mapping (mmap))</p><p>In previous sections, you learned how to read and write files using<code>read()</code> and<code>write()</code>. Those system calls move data between files and user-space buffers in RAM.</p><p>But what if you could map a file directly into memory, and then treat it as part of your process’s address space?</p><p>That’s exactly what memory mapping (via<code>mmap</code>) does, it’s faster, more flexible, and forms the backbone of databases, shared memory systems, and even virtual memory itself.</p><h4 id="step-1-what-is-mmap" tabindex="-1">Step 1. What Is mmap? <a class="header-anchor" href="#step-1-what-is-mmap" aria-label="Permalink to &quot;Step 1. What Is mmap?&quot;">​</a></h4><p><code>mmap()</code> maps a file or device into memory so you can access it directly, as if it were an array in RAM.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>void *mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset);</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>addr</code></td><td>Hint for mapping address (usually<code>NULL</code>)</td></tr><tr><td><code>length</code></td><td>Number of bytes to map</td></tr><tr><td><code>prot</code></td><td>Protection:<code>PROT_READ</code>,<code>PROT_WRITE</code>, etc.</td></tr><tr><td><code>flags</code></td><td>Type:<code>MAP_PRIVATE</code>,<code>MAP_SHARED</code>, etc.</td></tr><tr><td><code>fd</code></td><td>File descriptor to map</td></tr><tr><td><code>offset</code></td><td>Start offset in file (must be multiple of page size)</td></tr></tbody></table><h4 id="step-2-simple-file-mapping-example" tabindex="-1">Step 2. Simple File Mapping Example <a class="header-anchor" href="#step-2-simple-file-mapping-example" aria-label="Permalink to &quot;Step 2. Simple File Mapping Example&quot;">​</a></h4><p>Let’s map a file into memory and print its contents.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/stat.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;data.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) { perror(&quot;open&quot;); return 1; }</span></span>
<span class="line"><span>    struct stat st;</span></span>
<span class="line"><span>    fstat(fd, &amp;st);</span></span>
<span class="line"><span>    char *data = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);</span></span>
<span class="line"><span>    if (data == MAP_FAILED) { perror(&quot;mmap&quot;); return 1; }</span></span>
<span class="line"><span>    write(STDOUT_FILENO, data, st.st_size);</span></span>
<span class="line"><span>    munmap(data, st.st_size);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc mmap_read.c -o mmap_read</span></span>
<span class="line"><span>./mmap_read</span></span></code></pre></div><p>This directly prints the file contents, no loops, no<code>read()</code> calls.</p><h4 id="step-3-reading-vs-writing" tabindex="-1">Step 3. Reading vs. Writing <a class="header-anchor" href="#step-3-reading-vs-writing" aria-label="Permalink to &quot;Step 3. Reading vs. Writing&quot;">​</a></h4><p>If you want to modify a file through memory, you must open it read-write and use<code>PROT_WRITE</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/stat.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;memo.txt&quot;, O_RDWR | O_CREAT, 0666);</span></span>
<span class="line"><span>    ftruncate(fd, 64); // ensure file has enough size</span></span>
<span class="line"><span>    char *map = mmap(NULL, 64, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);</span></span>
<span class="line"><span>    if (map == MAP_FAILED) return 1;</span></span>
<span class="line"><span>    strcpy(map, &quot;Hello, memory-mapped file!&quot;);</span></span>
<span class="line"><span>    msync(map, 64, MS_SYNC);</span></span>
<span class="line"><span>    munmap(map, 64);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Open<code>memo.txt</code>, you’ll see the written text instantly.</p><ul><li><code>MAP_SHARED</code>: changes are written back to the file.</li><li><code>MAP_PRIVATE</code>: copy-on-write (changes visible only to this process).</li></ul><h4 id="step-4-anonymous-mappings" tabindex="-1">Step 4. Anonymous Mappings <a class="header-anchor" href="#step-4-anonymous-mappings" aria-label="Permalink to &quot;Step 4. Anonymous Mappings&quot;">​</a></h4><p>You can create memory that isn’t tied to any file, purely in RAM.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    size_t len = 4096;</span></span>
<span class="line"><span>    int *arr = mmap(NULL, len, PROT_READ | PROT_WRITE,</span></span>
<span class="line"><span>                    MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);</span></span>
<span class="line"><span>    if (arr == MAP_FAILED) return 1;</span></span>
<span class="line"><span>    arr[0] = 1234;</span></span>
<span class="line"><span>    printf(&quot;arr[0] = %d\\n&quot;, arr[0]);</span></span>
<span class="line"><span>    munmap(arr, len);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arr[0] = 1234</span></span></code></pre></div><p>Anonymous mappings are commonly used for dynamic memory regions or shared memory between processes.</p><h4 id="step-5-shared-memory-between-processes" tabindex="-1">Step 5. Shared Memory Between Processes <a class="header-anchor" href="#step-5-shared-memory-between-processes" aria-label="Permalink to &quot;Step 5. Shared Memory Between Processes&quot;">​</a></h4><p>You can use<code>MAP_SHARED</code> and<code>fork()</code> to let parent and child processes share the same mapped memory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *shared = mmap(NULL, sizeof(int),</span></span>
<span class="line"><span>                       PROT_READ | PROT_WRITE,</span></span>
<span class="line"><span>                       MAP_SHARED | MAP_ANONYMOUS,</span></span>
<span class="line"><span>                       -1, 0);</span></span>
<span class="line"><span>    *shared = 0;</span></span>
<span class="line"><span>    pid_t pid = fork();</span></span>
<span class="line"><span>    if (pid == 0) {</span></span>
<span class="line"><span>        (*shared)++;</span></span>
<span class="line"><span>        printf(&quot;Child: shared = %d\\n&quot;, *shared);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        sleep(1);</span></span>
<span class="line"><span>        printf(&quot;Parent: shared = %d\\n&quot;, *shared);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    munmap(shared, sizeof(int));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Child: shared = 1</span></span>
<span class="line"><span>Parent: shared = 1</span></span></code></pre></div><p>Both processes see the same memory, no pipes or sockets needed.</p><h4 id="step-6-memory-protections" tabindex="-1">Step 6. Memory Protections <a class="header-anchor" href="#step-6-memory-protections" aria-label="Permalink to &quot;Step 6. Memory Protections&quot;">​</a></h4><p>Use<code>PROT_*</code> flags to control access:</p><ul><li><code>PROT_READ</code>→ read allowed</li><li><code>PROT_WRITE</code>→ write allowed</li><li><code>PROT_EXEC</code>→ executable</li><li><code>PROT_NONE</code>→ no access</li></ul><p>You can change permissions later:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mprotect(ptr, len, PROT_READ);</span></span></code></pre></div><p>This helps you simulate “read-only” data regions or test segmentation faults intentionally.</p><h4 id="step-7-page-size-and-alignment" tabindex="-1">Step 7. Page Size and Alignment <a class="header-anchor" href="#step-7-page-size-and-alignment" aria-label="Permalink to &quot;Step 7. Page Size and Alignment&quot;">​</a></h4><p>Memory is mapped in units of pages (usually 4096 bytes). You can get your system’s page size:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Page size: %ld bytes\\n&quot;, sysconf(_SC_PAGESIZE));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Offsets in<code>mmap</code> must be aligned to page size.</p><h4 id="step-8-unmapping-and-syncing" tabindex="-1">Step 8. Unmapping and Syncing <a class="header-anchor" href="#step-8-unmapping-and-syncing" aria-label="Permalink to &quot;Step 8. Unmapping and Syncing&quot;">​</a></h4><p>When you’re done with a mapped region, always call:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>munmap(addr, length);</span></span></code></pre></div><p>If you modified the data:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msync(addr, length, MS_SYNC);</span></span></code></pre></div><p>This ensures changes are written back to disk.</p><h4 id="step-9-using-mmap-for-performance" tabindex="-1">Step 9. Using mmap for Performance <a class="header-anchor" href="#step-9-using-mmap-for-performance" aria-label="Permalink to &quot;Step 9. Using mmap for Performance&quot;">​</a></h4><p>Advantages over<code>read()</code> and<code>write()</code>:</p><ul><li>Avoids extra data copies between kernel and user space.</li><li>The OS loads only the pages you touch (lazy loading).</li><li>Efficient for random access to large files.</li></ul><p>Databases, editors, and browsers (like SQLite, Vim, Chrome) rely heavily on<code>mmap</code> for performance.</p><h4 id="tiny-code-count-lines-in-a-large-file" tabindex="-1">Tiny Code: Count Lines in a Large File <a class="header-anchor" href="#tiny-code-count-lines-in-a-large-file" aria-label="Permalink to &quot;Tiny Code: Count Lines in a Large File&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/mman.h&gt;</span></span>
<span class="line"><span>#include &lt;sys/stat.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;bigfile.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    struct stat st;</span></span>
<span class="line"><span>    fstat(fd, &amp;st);</span></span>
<span class="line"><span>    char *data = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);</span></span>
<span class="line"><span>    size_t lines = 0;</span></span>
<span class="line"><span>    for (size_t i = 0; i &lt; st.st_size; i++)</span></span>
<span class="line"><span>        if (data[i] == &#39;\\n&#39;) lines++;</span></span>
<span class="line"><span>    printf(&quot;Lines: %zu\\n&quot;, lines);</span></span>
<span class="line"><span>    munmap(data, st.st_size);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run it on a multi-GB file, it’ll perform incredibly fast.</p><h4 id="step-10-why-it-matters" tabindex="-1">Step 10. Why It Matters <a class="header-anchor" href="#step-10-why-it-matters" aria-label="Permalink to &quot;Step 10. Why It Matters&quot;">​</a></h4><p><code>mmap</code> opens a new world of memory-driven file access:</p><ul><li>Used by OSes to load executables, shared libs, and pages.</li><li>Powers databases, compilers, and search engines.</li><li>Enables shared memory between processes.</li><li>Reduces I/O overhead for large files.</li></ul><p>It’s the bridge between files and memory, unifying two key abstractions in C and Unix.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a file and modify it in place using<code>mmap</code>.</li><li>Create shared memory between parent and child processes with<code>MAP_SHARED</code>.</li><li>Measure performance difference between<code>read()</code> and<code>mmap</code>.</li><li>Map only part of a file using an offset aligned to page size.</li><li>Implement a small in-memory key-value store backed by<code>mmap</code>.</li></ol><p>Next, you’ll explore how to work with time and clocks in C, retrieving system timestamps, measuring durations, and implementing timers with precision.</p>`,61)])])}const u=s(t,[["render",i]]);export{h as __pageData,u as default};
